import{_ as l,o as t,c as o,a2 as r}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"篇887｜超脱者与法律·超脱者的法律豁免边界","description":"","frontmatter":{"title":"篇887｜超脱者与法律·超脱者的法律豁免边界","no":887,"module":4,"tags":["超脱","法律","法律豁免","紧急状态","边界"],"related":["789-法律约束与豁免边界","884-超脱者的法律约束","885-超脱者的法律责任","0048-司法体系与裁决机制"]},"headers":[],"relativePath":"zh/0887_模块4-超脱者与法律-法律豁免边界.md","filePath":"zh/0887_模块4-超脱者与法律-法律豁免边界.md"}'),i={name:"zh/0887_模块4-超脱者与法律-法律豁免边界.md"};function e(n,a,h,s,u,d){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="篇887-超脱者与法律·超脱者的法律豁免边界" tabindex="-1">篇887｜超脱者与法律·超脱者的法律豁免边界 <a class="header-anchor" href="#篇887-超脱者与法律·超脱者的法律豁免边界" aria-label="Permalink to &quot;篇887｜超脱者与法律·超脱者的法律豁免边界&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档789、884、885、48</p></blockquote><h2 id="引言-豁免不是特权——是紧急时刻不得不做的越权" tabindex="-1">引言：豁免不是特权——是紧急时刻不得不做的越权 <a class="header-anchor" href="#引言-豁免不是特权——是紧急时刻不得不做的越权" aria-label="Permalink to &quot;引言：豁免不是特权——是紧急时刻不得不做的越权&quot;">​</a></h2><p>旧世界的强者谈&quot;豁免&quot;，意思是&quot;我不受法律管&quot;。衡元宙谈&quot;豁免&quot;，意思完全不同：<strong>在某些极端紧急情况下，超脱者为了保护万族，不得不暂时突破某些常规法律程序——这种豁免不是特权，是被迫的越权，而且必须事后补正、接受审查。</strong> 本篇精确标定豁免的边界。</p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理要求豁免绝不变成掠夺的借口；万族共和公理要求豁免服务万族利益；集体升维公理要求豁免仅用于升维应急；因果自律公理要求豁免事后必须可追溯；法则优先公理要求豁免边界法则级自洽、不被滥用；众生全员无限均等公理确认所有生灵自带基础无限之力，佛系懒狗保有保底不被淘汰，卷王少年至尊可叠加更高无限——无限本源人人自带，掠夺自然失去意义。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、豁免不是什么" tabindex="-1">一、豁免不是什么 <a class="header-anchor" href="#一、豁免不是什么" aria-label="Permalink to &quot;一、豁免不是什么&quot;">​</a></h2><p>在讲豁免是什么之前，先讲豁免不是什么：</p><ul><li><strong>豁免不是特权</strong>：不是&quot;超脱者做什么都合法&quot;</li><li><strong>豁免不是常态</strong>：不是超脱者日常工作的默认状态</li><li><strong>豁免不是个人选择</strong>：不是超脱者自己觉得紧急就可以豁免</li><li><strong>豁免不是永久</strong>：不是一次豁免终身有效</li></ul><p>如果把豁免理解成特权，那就回到了旧世界&quot;强者逍遥法外&quot;的老路。</p><h2 id="二、豁免是什么-三种法定豁免情形" tabindex="-1">二、豁免是什么：三种法定豁免情形 <a class="header-anchor" href="#二、豁免是什么-三种法定豁免情形" aria-label="Permalink to &quot;二、豁免是什么：三种法定豁免情形&quot;">​</a></h2><p>衡元宙只承认三种法定豁免情形：</p><h3 id="情形一-外部掠夺派紧急入侵" tabindex="-1">情形一：外部掠夺派紧急入侵 <a class="header-anchor" href="#情形一-外部掠夺派紧急入侵" aria-label="Permalink to &quot;情形一：外部掠夺派紧急入侵&quot;">​</a></h3><p>当外部掠夺派势力对万族共和领土发动突袭，常规法律程序来不及启动时，超脱者有权：</p><ul><li>不经审批直接动用防御力量</li><li>不经审批直接进行跨位面反击</li><li>临时征用公共资源用于防御</li></ul><p>这种豁免的前提是：入侵是现实的、紧迫的、常规程序来不及的。</p><h3 id="情形二-法则网络崩溃应急" tabindex="-1">情形二：法则网络崩溃应急 <a class="header-anchor" href="#情形二-法则网络崩溃应急" aria-label="Permalink to &quot;情形二：法则网络崩溃应急&quot;">​</a></h3><p>当法则网络出现大规模崩溃——锚点断裂、法则节点失灵、阿赖耶系统瘫痪——超脱者有权：</p><ul><li>不经审批直接修复</li><li>临时绕故障节点重建连接</li><li>紧急调配资源抢险</li></ul><p>这种豁免的前提是：崩溃是系统性的、拖延会造成万族重大损失。</p><h3 id="情形三-文明级灾难救援" tabindex="-1">情形三：文明级灾难救援 <a class="header-anchor" href="#情形三-文明级灾难救援" aria-label="Permalink to &quot;情形三：文明级灾难救援&quot;">​</a></h3><p>当位面发生文明级灾难——恒星爆炸、黑暗置换体扩散、跨位面污染——超脱者有权：</p><ul><li>不经审批直接进入灾区</li><li>临时调动救援资源</li><li>在必要时临时疏散居民</li></ul><p>这种豁免的前提是：灾难规模超出常规应急能力。</p><h2 id="三、豁免的程序约束" tabindex="-1">三、豁免的程序约束 <a class="header-anchor" href="#三、豁免的程序约束" aria-label="Permalink to &quot;三、豁免的程序约束&quot;">​</a></h2><p>即使在三种豁免情形下，超脱者也必须遵守以下程序约束：</p><ol><li><strong>立即报告</strong>：豁免行动启动后，必须在最短时间内向锚点监督委员会报告</li><li><strong>事后补审</strong>：豁免行动结束后，必须接受阿赖耶网络+多层监督的完整审查</li><li><strong>必要性论证</strong>：超脱者必须证明&quot;不豁免就来不及&quot;——如果有常规程序的时间，就不能用豁免</li><li><strong>比例原则</strong>：豁免行动的规模必须与紧急程度相称——不能&quot;为了救一只鸡烧了一座城&quot;</li><li><strong>损害最小化</strong>：豁免行动造成的附带损害必须最小，事后必须修复</li></ol><h2 id="四、豁免的禁区" tabindex="-1">四、豁免的禁区 <a class="header-anchor" href="#四、豁免的禁区" aria-label="Permalink to &quot;四、豁免的禁区&quot;">​</a></h2><p>以下行为即使在紧急状态下也绝对不豁免：</p><ul><li>掠夺生灵本源（红线不可破）</li><li>篡改阿赖耶记录（红线不可破）</li><li>包庇掠夺派（红线不可破）</li><li>以豁免为名行个人目的（滥用豁免，从重处罚）</li><li>豁免结束后不补正、不审查（程序违规）</li></ul><p>禁区意味着：<strong>豁免只豁免程序，不豁免红线。</strong> 你可以紧急行动，但你不能趁机杀人放火。</p><p>豁免的设计哲学是：在紧急时刻，给超脱者足够的行动自由；在非紧急时刻，给他足够的约束。这不是矛盾，而是平衡——太松了他会滥用，太紧了他在紧急时刻来不及反应。法律的艺术就在这个松紧之间。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：豁免制度让超脱者在紧急时刻不用走冗长程序，节省应急时间</li><li><strong>反掠夺</strong>：豁免严格限定在应急场景，绝不变成掠夺借口</li><li><strong>唐罗上限对比</strong>：唐罗的&quot;豁免&quot;是永久的——他做什么都合法；衡元宙的豁免是临时的、法定的、事后必须审查的</li><li><strong>万族全覆盖</strong>：豁免只用于保护万族，不用于保护超脱者个人</li><li><strong>超多元全开放</strong>：豁免触发记录、事后审查报告全部通过无私道全网公开</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>法律豁免不是特权，是紧急时刻不得不做的越权。它只有三种法定情形：外部入侵、法则崩溃、文明灾难。即使在豁免中，红线不可破，程序必须补正，事后必须审查。豁免是暂时放下规矩去救火，火灭了必须重新把规矩立起来——而且要让人查清楚你有没有趁救火的时候偷东西。这，才是超脱者法律豁免边界的正统定义。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./0789_模块4-制度-法律约束与豁免边界.html">789-法律约束与豁免边界</a> · <a href="./0884_模块4-超脱者与法律-法律约束.html">884-超脱者的法律约束</a> · <a href="./0885_模块4-超脱者与法律-法律责任.html">885-超脱者的法律责任</a> · <a href="./0048-司法体系与裁决机制.html">0048-司法体系与裁决机制</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',38)])])}const q=l(i,[["render",e]]);export{_ as __pageData,q as default};
